SELECT 



        quota.user_code LIKE CONCAT('%', #{query.userCode}, '%')


        AND downgrade.downgrade_status = #{query.downgradeStatus}


        AND downgrade.request_type = #{query.requestType}


ORDER BY downgrade.requested_time DESC NULLS LAST, downgrade.downgrade_id DESC

SELECT 

WHERE downgrade.user_id = #{userId}

    AND downgrade.downgrade_status = #{query.downgradeStatus}


    AND downgrade.request_type = #{query.requestType}

ORDER BY downgrade.requested_time DESC NULLS LAST, downgrade.downgrade_id DESC
